package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** Takes the sheet's next claim number. The update locks the sheet's row until the transaction
     *  ends, so claims opened at the same moment are numbered one after the other. */
    @Modifying
    @Query(value = "UPDATE sheet SET claim_numbers = claim_numbers + 1 WHERE id = :sheetId", nativeQuery = true)
    int takeClaimNumber(@Param("sheetId") String sheetId);

    @Query(value = "SELECT claim_numbers FROM sheet WHERE id = :sheetId", nativeQuery = true)
    int lastClaimNumber(@Param("sheetId") String sheetId);

    /** The claim's status as stored now, read past the loaded entity. */
    @Query(value = "SELECT status FROM claim WHERE id = :id", nativeQuery = true)
    String storedStatus(@Param("id") Long id);
}
EOF
cat > $J/claim/OpenClaim.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Moves the claim to OPEN, refusing it when its status does not allow that, and gives it the sheet's
 *  next number. */
public class OpenClaim {
    public void apply(@Val Claim claim, ClaimRepository repository) throws InvalidClaimStatusException {
        ClaimTransition.to(claim, ClaimStatus.OPEN);
        repository.takeClaimNumber(claim.getSheetId());
        // With the sheet's numbers held, re-check the stored status: an open of the same claim that
        // got there first has committed by now, and this one is refused (rolling the number back).
        ClaimTransition.check(ClaimStatus.valueOf(repository.storedStatus(claim.getId())), ClaimStatus.OPEN);
        claim.setNumber(repository.lastClaimNumber(claim.getSheetId()));
    }
}
EOF
cat > $J/claim/ClaimTransition.java <<'EOF'
package net.officefloor.hq.app.claim;

/** Moves a claim to a new status, refusing a change its current status does not allow. */
final class ClaimTransition {
    private ClaimTransition() {
    }

    static void to(Claim claim, ClaimStatus to) throws InvalidClaimStatusException {
        check(claim.getStatus(), to);
        claim.setStatus(to);
    }

    static void check(ClaimStatus from, ClaimStatus to) throws InvalidClaimStatusException {
        if (!from.canBecome(to)) {
            throw new InvalidClaimStatusException("A " + from + " claim cannot become " + to + ".");
        }
    }
}
EOF
